private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int len = bb.limit() - i;
    for (int k = 0; k < len && i < bb.limit(); k++, i++) {
        /* characters decoded include: BOM byte & null byte character */
        int utfChar = bb.get(i);
        if ((utfChar & 0xFF00) == 0xFEFF) { // BOM byte detected
            utfChar = (utfChar & 0xFF);
        }
        if ((utfChar & 0xF000) == 0xD800) { // high surrogate detected
            if (i < bb.limit() - 1 && (bb.get(i + 1) & 0xFC00) == 0xDC00) { // low surrogate detected
                utfChar = 0x10000 + ((utfChar & 0x3FF) << 10) + (bb.get(i + 1) & 0x3FF);
                i++;
            }
        }
        sb.append((char) utfChar);
    }
    return i;
}

