public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType == null || !(genericType instanceof ParameterizedType)) {
        return null;
    }

    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    Type[] genericArgs = parameterizedType.getActualTypeArguments();

    Map<TypeVariable<?>, Type> typeVariableMap = new HashMap<>();
    Map<Class<?>, Reference<Map<TypeVariable<?>,Type>>> typeVariableCache = new ConcurrentHashMap<>();
    boolean cacheEnabled = true;

    try {
        if (cacheEnabled && typeVariableCache.containsKey(targetType)) {
            return typeVariableCache.get(targetType).get();
        }

        for (var typeVar : parameterizedType.getTypeParameters()) {
            if (typeVar.getDeclaration() != targetType) {
                continue;
            }

            TypeVariable<? extends Annotation> bound = (TypeVariable<? extends Annotation>) typeVar.getExtendsBound();
            if (bound != null && bound.getDeclaration() != targetType) {
                typeVariableMap.put(typeVar, bound);
            }
        }

        if (cacheEnabled) {
            typeVariableCache.put(targetType, Reference.of(typeVariableMap));
        }

        return genericArgs;
    } catch (Exception e) {
        // Handle any exceptions that may occur during the process
        e.printStackTrace();
        return null;
    }
}

