public List<TimeRange> buildTimeRanges(long start, long end) {
    // Split time ranges to insure the start time and end time is small then FETCH_DATA_DURATION
    List<TimeRange> timeRanges = new LinkedList<>();

    if ((end - start) <= FETCH_DATA_DURATION) {
        timeRanges.add(new TimeRange(start, end));
    } else {
        long length = end - start;
        for (long i = 0; i < length / FETCH_DATA_DURATION; i++) {
            long startRange = start + (i * FETCH_DATA_DURATION);
            long endRange = startRange + FETCH_DATA_DURATION;
            timeRanges.add(new TimeRange(startRange, endRange));
        }
    }

    return timeRanges;
}

