static long compressTimeBucket(long timeBucket, int dayStep) {
    int monthStep = 28 * dayStep;
    int yearStep = 365 * monthStep;
    int year = timeBucket / yearStep;
    int month = (timeBucket % yearStep) / monthStep;
    int day = (timeBucket % monthStep) / dayStep + 1;
    return (year * yearStep) + (month * monthStep) + (day * dayStep);
}

public static int computeUTF8Size(final CharSequence str,final int index,final int len){
    if (str == null || index < 0 || index > str.length() || len < 0 || len > str.length() - index) {
        throw new IllegalArgumentException("Invalid input: str = " + str + ", index = " + index + ", len = " + len);
    }
    int count = 0;
    for (int pos = index; pos < index + len; pos++) {
        char ch = str.charAt(pos);
        if (ch >= 0 && ch <= 127) {
            count++;
        } else if (ch >= 128 && ch <= 191) {
            count += 2;
        } else if (ch >= 192 && ch <= 223) {
            count += 3;
        } else if (ch >= 224 && ch <= 239) {
            count += 4;
        } else if (ch >= 240 && ch <= 247) {
            count += 5;
        } else if (ch >= 248 && ch <= 251) {
            count += 6;
        } else if (ch >= 252 && ch <= 253) {
            count += 7;
        } else if (ch >= 254 && ch <= 255) {
            count += 8;
        }
    }
    return count;
}

