public static void writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null || lb == null) {
        throw new IllegalArgumentException("Input characters or LinkedBuffer cannot be null.");
    }

    int area = lb.getArea();
    byte[] srcBytes = new byte[str.length() * 3]; // Estimate to be UTF-8 encoding + 1 for null terminator
    try {
        int written = 0;
        int index = 0;
        if (area >= srcBytes.length) {
            lb.resize(srcBytes.length * 2); // Increase area if needed
        }
        for (char c : str) {
            if (c <= 0x7f) {
                srcBytes[index++] = (byte) c;
            } else if (c <= 0x7ff) {
                srcBytes[index++] = (byte) ((0b1100_0000 | (c >> 6)) & 0xFF);
                srcBytes[index++] = (byte) ((0b1000_0000 | (c & 0x3f)) & 0xFF);
            } else if (c <= 0xffff) {
                srcBytes[index++] = (byte) ((0b1111_0000 | (c >> 12)) & 0xFF);
                srcBytes[index++] = (byte) ((0b1000_0000 | ((c >> 6) & 0x3F)) & 0xFF);
                srcBytes[index++] = (byte) ((0b1000_0000 | (c & 0x3F)) & 0xFF);
            } else if (c <= 0x10ffff) {
                srcBytes[index++] = (byte) ((0b1111_0000 | (c >> 18)) & 0xFF);
                srcBytes[index++] = (byte) ((0b1000_0000 | ((c >> 12) & 0x3F)) & 0xFF);
                srcBytes[index++] = (byte) ((0b1000_0000 | ((c >> 6) & 0x3F)) & 0xFF);
                srcBytes[index++] = (byte) ((0b1000_0000 | (c & 0x3F)) & 0xFF);
            } else {
                throwBadUtf8("Invalid UTF-8 sequence.");
            }
            written += 1;
            if (written >= lb.getWriteableSize()) {
                lb.resize(2 * area); // Increase size if needed
            }
        }
        srcBytes[index] = 0; // Null terminator
        lb.setResizeable(false);
        lb.setPosition(0);
        lb.write(srcBytes);
    } catch (IOException e) {
        // Handle I/O errors
        throw new RuntimeException("Error writing UTF-8 to LinkedBuffer.", e);
    }
}

