private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase){
    if (str == null || suffix == null) {
        return str == suffix ? true : false;
    }

    final int lenStr = str.length();
    final int lenSuffix = suffix.length();
    if (lenSuffix > lenStr) {
        return false;
    }

    if (ignoreCase) {
        str = str.toLowerCase();
        suffix = suffix.toLowerCase();
    }

    for (int i = 0; i < lenSuffix; i++) {
        if (str.charAt(lenStr - 1 - i) != suffix.charAt(lenSuffix - 1 - i)) {
            return false;
        }
    }

    return true;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    if (u == null) {
          return null;
    }

    String path = u.getPath();
    if (path == null || path.isEmpty()) {
          return List.of();
    }

    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    StringBuilder segmentBuilder = new StringBuilder();

    for (int i = 0; i < path.length(); i++) {
        char ch = path.charAt(i);
        if (ch == '/') {
            if (segmentBuilder.length() > 0) {
                if (!decode) {
                    segmentBuilder.append(ch);
                } else {
                    pathSegments.add(new PathSegmentImpl(decodeValue(segmentBuilder.toString())));
                }
                segmentBuilder.setLength(0);
            }
        } else {
            segmentBuilder.append(ch);
        }
    }

    if (!segmentBuilder.isEmpty()) {
        if (!decode) {
            segmentBuilder.append('/'); // Append the trailing slash
        } else {
            pathSegments.add(new PathSegmentImpl(decodeValue(segmentBuilder.toString())));
        }
    }

    return pathSegments;
}

