public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 0) {
        throw new IllegalArgumentException("Capacity cannot be negative");
    }
    if (desiredCapacity < 1000) {
        desiredCapacity = (int)(desiredCapacity * 1.1);
    }
    int prime = primeCapacities[preferredIndex(desiredCapacity)];
    if (prime <= desiredCapacity) {
        do {
            prime += 2;
            while (isComposite(prime, primeCapacities)) {
                prime += 2;
            }
        } while (prime <= desiredCapacity);
    }
    return prime;
}

