public short readShort(final int offset) {
    // Check for valid offset
    if (offset < 0 || offset > 7) {
        throw new IndexOutOfBoundsException("Offset must be in the range 0-7");
    }

    // Read the byte at the specified offset
    byte currentByte = readByte(offset);

    // Read the lower nibble of the byte
    short lowerNibble = (short) (currentByte & 0xF);

    // Read the upper nibble of the byte
    short upperNibble = (short) ((currentByte >> 4) & 0xF);

    // Combine the lower and upper nibbles to form the short
    short result = (short) ((upperNibble << 4) | lowerNibble);

    return result;
}

