private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false; // Null node indicates no deletion.
    }

    // Assume the implementation of ListNodeImpl and list manipulation.

    // Remove from the end of the list if it's not the head.
    if (this.last == node) {
        this.last = node.prev;
    }

    // Remove from the beginning of the list if it's not the tail.
    if (this.first == node) {
        this.first = node.next;
    }

    // Remove links between node and its neighbors.
    if (node.prev != null) {
        node.prev.next = node.next;
    }
    if (node.next != null) {
        node.next.prev = node.prev;
    }

    // Optional: Mark the node as has been removed.
    node.isRemoved = true;

    return true;
}

